use super::*;use crate::original_combat::OriginalRng;
fn mix(h:&mut u32,n:u32){*h=(*h^n).wrapping_mul(16777619);}fn hash(bytes:impl IntoIterator<Item=u8>)->u32{let mut h=2166136261;for n in bytes{mix(&mut h,u32::from(n));}h}
fn free(slot:usize,cap:usize,p:usize)->bool{match p{0=>false,1=>true,2=>slot==0,3=>slot==cap.wrapping_sub(1),4=>slot%2==0,5=>[1,7,31,99,499].contains(&slot),6=>slot<7,_=>slot<10}}
struct Fixture{records:Vec<[u8;44]>,limit:usize,rng:OriginalRng,mode:u8,calls:u32,trace:u32,slots:u32,allocations:u32,first:Option<usize>,last:Option<usize>,selected:usize,source:Option<usize>,requests:u32,request_trace:u32,group:u8,groups:[u32;2],at_first:u32,at_second:u32,at_retire:u32}
impl Fixture{fn new(s:usize,limit:usize,pattern:usize,mp:bool,mode:u8)->Self{Self{records:(0..500).map(|slot|{let mut p=std::array::from_fn(|j|(s*17+slot*13+j*19)as u8);p[..2].copy_from_slice(&(if free(slot,limit,pattern){-1000i16}else{[0,-1,999][slot%3]}).to_le_bytes());p}).collect(),limit,rng:OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(s as u32*7919).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:mp},mode,calls:0,trace:2166136261,slots:2166136261,allocations:0,first:None,last:None,selected:0,source:None,requests:0,request_trace:2166136261,group:0,groups:[0;2],at_first:0,at_second:0,at_retire:0}}
 fn hash(&self)->u32{hash(self.records.iter().flatten().copied())}
}
impl Pool for Fixture{
 fn first_free(&self)->Option<usize>{(0..self.limit).find(|&i|i16::from_le_bytes(self.records[i][..2].try_into().unwrap())==-1000)}
 fn load(&mut self,slot:usize)->[u8;44]{self.selected=slot;self.records[slot]}
 fn store(&mut self,slot:usize,record:[u8;44]){assert_ne!(Some(slot),self.source);self.records[slot]=record;self.allocations+=1;mix(&mut self.slots,slot as u32);self.first.get_or_insert(slot);self.last=Some(slot);if self.group!=0{self.groups[usize::from(self.group-1)]+=1;}}
 fn random(&mut self)->u32{if let Some(source)=self.source{assert_eq!(i16::from_le_bytes(self.records[source][..2].try_into().unwrap()),0);}let site=if self.mode==0{self.calls%5}else if self.calls==0{0}else{(self.calls-1)%6+1};let v=self.rng.next_u32();mix(&mut self.trace,site);mix(&mut self.trace,self.selected as u32);mix(&mut self.trace,v);self.calls+=1;v}
}
impl World for Fixture{
 fn retire(&mut self,slot:usize){assert_eq!(self.source,Some(slot));self.at_retire=self.calls;assert_eq!(i16::from_le_bytes(self.records[slot][..2].try_into().unwrap()),0);self.records[slot][..2].copy_from_slice(&(-1000i16).to_le_bytes());}
 fn before_emit(&mut self,_count:u16,g:&Globals){if self.mode!=0{if self.requests==0{self.at_first=self.calls;self.group=1;}else{self.at_second=self.calls;self.group=2;}}self.requests+=1;for n in[g.context.origin[0]as u32,g.context.origin[1]as u32,g.raw.payload36,g.raw.payload40,u32::from(g.raw.byte32),g.context.sprite as u32,u32::from(g.maximum),u32::from(g.context.tint),u32::from(g.context.flags),u32::from(g.context.fade),u32::from(g.context.owner),u32::from(g.suppression),g.raw.constructor.unwrap()]{mix(&mut self.request_trace,n);}}
}
fn globals(s:usize,gate:u8,flags:u8,payload:u32,command:u32)->Globals{Globals{context:Context{origin:[-1234,2345],tint:(s*31)as u8,flags,fade:3,owner:3,sprite:557},maximum:99,suppression:gate,raw:Raw{byte32:(s*23)as u8,payload36:payload,payload40:0x1900000+s as u32*44,command,last_record:Some(0xdeadbeef),constructor:Some(0x12345678)}}}
fn oracle(name:&str)->Option<Vec<serde_json::Value>>{std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("../../../work/parity-audit/{name}"))).ok().map(|s|s.lines().map(|l|serde_json::from_str(l).unwrap()).collect())}
fn compare(row:&serde_json::Value,names:&[&str],values:&[u32],w:&Fixture){for(k,&value)in names.iter().zip(values){assert_eq!(row[k].as_i64().unwrap()as u32,value,"scenario{}:{k}",row["scenario"]);}let hex=|b:&[u8]|b.iter().map(|n|format!("{n:02x}")).collect::<String>();if let Some(slot)=w.first{assert_eq!(row["firstBytes"],hex(&w.records[slot]));}if let Some(slot)=w.last{assert_eq!(row["lastBytes"],hex(&w.records[slot]));}if let Some(slot)=w.source{assert_eq!(row["sourceBytes"],hex(&w.records[slot]));}}
#[test]fn native_2560_bridge_prefixes_match_requests_raw44_globals_fullpool_and_five_rng_calls(){
 let rows=oracle("v40-bridge-prefix.jsonl");let mut all=2166136261;
 for s in 0..2560usize{let world=s%5;let orientation=s/5%2;let cap=[0,1,12,500][s/10%4];let pattern=s/40%8;let half=s/320%2;let gate=s/640%2;let mp=s/1280%2;let span=[-32768,-1,0,16,31,32,33,48,96,128,256][s/7%11];let x=[346,-32768,32767,0][s/9%4];let y=[420,32767,-32768,-1][s/11%4];let payload=if s/13%2==0{0x1800000+s as u32*40}else{0xfffffff0};let mut w=Fixture::new(s,cap,pattern,mp!=0,0);let before=w.hash();let mut g=globals(s,gate as u8,7,payload,0xabcd1234);let sprite=native_sprites(world).unwrap().prefix;let made=prefix(&mut w,&mut g,[x,y],if orientation==0{[span,48]}else{[48,span]},orientation as i16,half!=0,sprite);assert_eq!(made as u32,w.allocations);
  let values=[s as u32,world as u32,orientation as u32,cap as u32,pattern as u32,half as u32,gate as u32,mp as u32,span as u32,x as u32,y as u32,sprite as u32,payload,before,w.hash(),w.calls,w.trace,w.requests,w.request_trace,w.allocations,w.slots,w.first.map_or(u32::MAX,|n|n as u32),w.last.map_or(u32::MAX,|n|n as u32),g.context.origin[0]as u32,g.context.origin[1]as u32,u32::from(g.context.tint),u32::from(g.maximum),u32::from(g.context.flags),u32::from(g.context.fade),u32::from(g.context.owner),g.context.sprite as u32,g.raw.constructor.unwrap(),g.raw.last_record.unwrap(),g.raw.payload36,g.raw.payload40,g.raw.command,u32::from(g.suppression),w.rng.words[0],w.rng.words[1],w.rng.words[2],w.rng.words[3],w.rng.words[4]];for n in values{mix(&mut all,n);}if let Some(rows)=&rows{compare(&rows[s],&["scenario","world","orientation","capacity","pattern","half","gate","mp","span","x","y","worldSprite","inputPayload","before","hash","calls","trace","requests","requestTrace","allocations","slots","first","last","originX","originY","tint","maximum","flags","fade","owner","sprite","constructor","queuePointer","payload36","payload40","command","suppression","r0","r1","r2","r3","r4"],&values,&w);}
 }assert_eq!(all,265808217,"actual09a60/09870/402160/401170/403370/4609a0/460910, all500x44 bytes and request globals before every attempt");
}
